insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by, subject) values ('6d53eeda-152d-5b9f-a127-8127bf0bcf7a', (select id from public.topics where id = '004396a5-19db-5ac6-9df6-126e61518dca'), 'Grade 9 · Biology · Body systems · Criterion A unit test', 'Summative test for MYP 4 (Grade 9) Biology, Unit 4 Body systems. Criterion A: Knowing and understanding. Statement of inquiry: evidence of healthy wellbeing is a consequence of the proper functioning of systems. Sections: 1 Respiratory system, 2 Nervous system, 3 Muscular and skeletal systems, 4 Homeostasis. Answer every question. Use the command terms (state, describe, outline, explain). Written answers are marked against the mark scheme; your teacher checks every mark. 78 marks, 70 minutes.', 70, 1, true, true, 'exam', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', 'Biology') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, time_limit_minutes = excluded.time_limit_minutes, category = 'exam', subject = excluded.subject, topic_id = excluded.topic_id;
