insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('081406ba-5402-571a-b017-adcb0f6f2bfd', (select id from public.topics where id = '004396a5-19db-5ac6-9df6-126e61518dca'), 'short', 'Outline the process of inhalation (breathing in).', '[]'::jsonb, 4, 'Respiratory system', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('081406ba-5402-571a-b017-adcb0f6f2bfd', 'The diaphragm contracts and flattens [1]; the external intercostal muscles contract and pull the ribs up and out [1]; the volume of the thorax increases [1]; the pressure in the lungs decreases so air flows in [1].', 'The diaphragm contracts and flattens [1]; the external intercostal muscles contract and pull the ribs up and out [1]; the volume of the thorax increases [1]; the pressure in the lungs decreases so air flows in [1].', '[{"text": "The diaphragm contracts and flattens", "any": ["diaphragm contracts", "diaphragm flattens", "diaphragm moves down"], "all": [], "marks": 1}, {"text": "The external intercostal muscles contract and pull the ribs up and out", "any": ["intercostal", "ribs up", "ribs move up", "ribs out"], "all": [], "marks": 1}, {"text": "The volume of the thorax increases", "any": ["volume increases", "volume of the thorax increases", "larger volume", "volume of the chest increases"], "all": [], "marks": 1}, {"text": "The pressure in the lungs decreases so air flows in", "any": ["pressure decreases", "pressure falls", "lower pressure", "air flows in", "air rushes in"], "all": [], "marks": 1}]'::jsonb, 'The diaphragm contracts and flattens [1]; the external intercostal muscles contract and pull the ribs up and out [1]; the volume of the thorax increases [1]; the pressure in the lungs decreases so air flows in [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
