insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('032a23ff-ebd1-5a71-8ee9-cffdafad7923', (select id from public.topics where id = '004396a5-19db-5ac6-9df6-126e61518dca'), 'short', 'Explain the relationship between the form and the function of the alveoli. Refer to three features.', '[]'::jsonb, 3, 'Respiratory system', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('032a23ff-ebd1-5a71-8ee9-cffdafad7923', 'Millions of alveoli give a very large surface area, so more gas diffuses at once [1]; their walls are one cell thick, giving a short diffusion distance [1]; a dense capillary network keeps the concentration gradient steep [1].', 'Millions of alveoli give a very large surface area, so more gas diffuses at once [1]; their walls are one cell thick, giving a short diffusion distance [1]; a dense capillary network keeps the concentration gradient steep [1].', '[{"text": "Millions of alveoli give a very large surface area, so more gas diffuses at once", "any": ["surface area", "large area", "many alveoli"], "all": [], "marks": 1}, {"text": "Their walls are one cell thick, giving a short diffusion distance", "any": ["thin", "one cell", "short distance"], "all": [], "marks": 1}, {"text": "A dense capillary network keeps the concentration gradient steep", "any": ["capillar", "blood supply", "moist", "gradient", "ventilat"], "all": [], "marks": 1}]'::jsonb, 'Millions of alveoli give a very large surface area, so more gas diffuses at once [1]; their walls are one cell thick, giving a short diffusion distance [1]; a dense capillary network keeps the concentration gradient steep [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
