insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('8fd128ff-ec04-598b-a721-bf0980dbd6ea', (select id from public.topics where id = '004396a5-19db-5ac6-9df6-126e61518dca'), 'short', 'Distinguish between breathing and respiration.', '[]'::jsonb, 2, 'Respiratory system', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8fd128ff-ec04-598b-a721-bf0980dbd6ea', 'Breathing is the movement of air into and out of the lungs [1]; respiration is a chemical reaction in cells that releases energy from glucose [1].', 'Breathing is the movement of air into and out of the lungs [1]; respiration is a chemical reaction in cells that releases energy from glucose [1].', '[{"text": "Breathing is the movement of air into and out of the lungs", "any": ["air", "in and out", "into and out", "ventilation"], "all": [], "marks": 1}, {"text": "Respiration is a chemical reaction in cells that releases energy from glucose", "any": ["reaction", "release energy", "releases energy", "glucose", "cells"], "all": [], "marks": 1}]'::jsonb, 'Breathing is the movement of air into and out of the lungs [1]; respiration is a chemical reaction in cells that releases energy from glucose [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
