insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('fc1856ca-b70f-5742-9ba9-410d229731a2', (select id from public.topics where id = '004396a5-19db-5ac6-9df6-126e61518dca'), 'short', 'Explain why exhaled air contains less oxygen and more carbon dioxide than inhaled air.', '[]'::jsonb, 2, 'Respiratory system', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fc1856ca-b70f-5742-9ba9-410d229731a2', 'Oxygen diffuses into the blood and is used by cells [1]; carbon dioxide is produced by respiration in the cells and diffuses into the alveoli to be breathed out [1].', 'Oxygen diffuses into the blood and is used by cells [1]; carbon dioxide is produced by respiration in the cells and diffuses into the alveoli to be breathed out [1].', '[{"text": "Oxygen diffuses into the blood and is used by cells", "any": ["oxygen", "diffuses into the blood", "used"], "all": [], "marks": 1}, {"text": "Carbon dioxide is produced by respiration in the cells and diffuses into the alveoli to be breathed out", "any": ["respiration", "produced", "made by cells", "cells make"], "all": [], "marks": 1}]'::jsonb, 'Oxygen diffuses into the blood and is used by cells [1]; carbon dioxide is produced by respiration in the cells and diffuses into the alveoli to be breathed out [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6d53eeda-152d-5b9f-a127-8127bf0bcf7a', 'fc1856ca-b70f-5742-9ba9-410d229731a2', 10);
