insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('47fdc824-04c3-531a-a75d-d4074506c9f5', (select id from public.topics where id = '004396a5-19db-5ac6-9df6-126e61518dca'), 'short', 'Describe and explain how the body detects and restores its temperature when it becomes too hot.', '[]'::jsonb, 4, 'Homeostasis', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('47fdc824-04c3-531a-a75d-d4074506c9f5', 'Receptors in the hypothalamus detect the rise in blood temperature [1]; sweat glands release sweat [1], which evaporates and removes heat energy from the skin [1]; vasodilation widens the skin arterioles so more blood flows near the surface and more heat is lost [1].', 'Receptors in the hypothalamus detect the rise in blood temperature [1]; sweat glands release sweat [1], which evaporates and removes heat energy from the skin [1]; vasodilation widens the skin arterioles so more blood flows near the surface and more heat is lost [1].', '[{"text": "Receptors in the hypothalamus detect the rise in blood temperature", "any": ["hypothalamus", "receptor"], "all": [], "marks": 1}, {"text": "Sweat glands release sweat", "any": ["sweat"], "all": [], "marks": 1}, {"text": "Which evaporates and removes heat energy from the skin", "any": ["evaporat", "heat energy", "takes heat"], "all": [], "marks": 1}, {"text": "Vasodilation widens the skin arterioles so more blood flows near the surface and more heat is lost", "any": ["vasodilation", "widen", "more blood", "surface"], "all": [], "marks": 1}]'::jsonb, 'Receptors in the hypothalamus detect the rise in blood temperature [1]; sweat glands release sweat [1], which evaporates and removes heat energy from the skin [1]; vasodilation widens the skin arterioles so more blood flows near the surface and more heat is lost [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
