insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d2dd4c5a-1ee1-5b6b-b656-7e1d1dc39c4b', 'The pancreas detects the rise in blood glucose [1] and releases insulin [1]; insulin makes cells take up glucose and the liver store it as glycogen [1].', 'The pancreas detects the rise in blood glucose [1] and releases insulin [1]; insulin makes cells take up glucose and the liver store it as glycogen [1].', '[{"text": "The pancreas detects the rise in blood glucose", "any": ["pancreas", "detect"], "all": [], "marks": 1}, {"text": "Releases insulin", "any": ["insulin"], "all": [], "marks": 1}, {"text": "Insulin makes cells take up glucose and the liver store it as glycogen", "any": ["glycogen", "liver", "take up", "store"], "all": [], "marks": 1}]'::jsonb, 'The pancreas detects the rise in blood glucose [1] and releases insulin [1]; insulin makes cells take up glucose and the liver store it as glycogen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
