insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d1e0b868-0deb-54c4-a7a8-dd149e0a6fc0', 'The hypothalamus detects that the blood has too little water [1]; the pituitary gland releases more ADH [1]; the kidneys reabsorb more water, making a small volume of concentrated urine [1].', 'The hypothalamus detects that the blood has too little water [1]; the pituitary gland releases more ADH [1]; the kidneys reabsorb more water, making a small volume of concentrated urine [1].', '[{"text": "The hypothalamus detects that the blood has too little water", "any": ["hypothalamus", "detect"], "all": [], "marks": 1}, {"text": "The pituitary gland releases more ADH", "any": ["adh", "pituitary"], "all": [], "marks": 1}, {"text": "The kidneys reabsorb more water, making a small volume of concentrated urine", "any": ["reabsorb", "kidney", "concentrated", "less urine"], "all": [], "marks": 1}]'::jsonb, 'The hypothalamus detects that the blood has too little water [1]; the pituitary gland releases more ADH [1]; the kidneys reabsorb more water, making a small volume of concentrated urine [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
